   454→        // 分离逢人配和普通牌
   455→        const trumpCards = cards.filter(c => c.isTrump); // 逢人配（红桃级牌）
   456→        const normalCards = cards.filter(c => !c.isTrump && !c.isJoker);
   457→        const hasJoker = cards.some(c => c.isJoker);
   458→
   459→        // 获取牌的原始值
   460→        const getValue = (c) => RANK_VALUES[c.rank] || c.value;
   461→
   462→        // 单张
   463→        if (cards.length === 1) return { valid: true, type: 'single', value: cards[0].value };
   464→
   465→        // 对子：两张相同，或一张普通牌+一张逢人配
   466→        if (cards.length === 2) {
   467→            // 两张大王或两张小王可以作为对子
   468→            const bigJokers = cards.filter(c => c.rank === '大王');
   469→            const smallJokers = cards.filter(c => c.rank === '小王');
   470→            if (bigJokers.length === 2) {
   471→                return { valid: true, type: 'pair', value: 16.5 };
   472→            }
   473→            if (smallJokers.length === 2) {
   474→                return { valid: true, type: 'pair', value: 15.5 };
   475→            }
   476→
   477→            if (!hasJoker) {
   478→                if (trumpCards.length === 2) {
   479→                    // 两张逢人配变成最大的对子
   480→                    return { valid: true, type: 'pair', value: 14.5 };
   481→                }
   482→                if (trumpCards.length === 1) {
   483→                    // 一张逢人配 + 一张普通牌 = 该普通牌的对子
   484→                    return { valid: true, type: 'pair', value: normalCards[0].value };
   485→                }
   486→                if (normalCards.length === 2 && normalCards[0].value === normalCards[1].value) {
   487→                    return { valid: true, type: 'pair', value: normalCards[0].value };
   488→                }
   489→            }
   490→        }
   491→
   492→        // 王炸
   493→        if (cards.length === 4 && cards.filter(c => c.rank === '大王').length === 2 && cards.filter(c => c.rank === '小王').length === 2) {
   494→            return { valid: true, type: 'rocket', value: 100 };
   495→        }
   496→
   497→        // 三张：三张相同，或2张普通牌+1张逢人配，或1张普通牌+2张逢人配
   498→        if (cards.length === 3 && !hasJoker) {
