   500→                return { valid: true, type: 'triple', value: 14.5 };
   501→            }
   502→            if (trumpCards.length === 2) {
   503→                return { valid: true, type: 'triple', value: normalCards[0].value };
   504→            }
   505→            if (trumpCards.length === 1 && normalCards.length === 2 && normalCards[0].value === normalCards[1].value) {
   506→                return { valid: true, type: 'triple', value: normalCards[0].value };
