   740→    comparePlay(newPlay, lastPlay) {
   741→        if (!lastPlay) return true;
   742→        if (newPlay.type === 'rocket') return true;
   743→        if (lastPlay.type === 'rocket') return false;
   744→
   745→        // 同花顺作为炸弹，可以压普通牌型
   746→        if (newPlay.type === 'straightFlush' && lastPlay.type !== 'bomb' && lastPlay.type !== 'straightFlush' && lastPlay.type !== 'rocket') {
   747→            return true;
   748→        }
   749→
   750→        // 同花顺 vs 炸弹：6张炸弹 > 同花顺 > 5张炸弹
   751→        if (newPlay.type === 'straightFlush' && lastPlay.type === 'bomb') {
   752→            return lastPlay.length < 6; // 同花顺能压5张炸弹，压不了6张炸弹
   753→        }
   754→        if (lastPlay.type === 'straightFlush' && newPlay.type === 'bomb') {
   755→            return newPlay.length >= 6; // 只有6张及以上的炸弹能压同花顺
   756→        }
   757→
   758→        if (newPlay.type === 'bomb' && lastPlay.type !== 'bomb' && lastPlay.type !== 'straightFlush') return true;
   759→        if (lastPlay.type === 'bomb' && newPlay.type !== 'bomb' && newPlay.type !== 'straightFlush') return false;
   760→
   761→        if (newPlay.type === lastPlay.type) {
   762→            if (newPlay.type === 'bomb') {
   763→                if (newPlay.length > lastPlay.length) return true;
   764→                if (newPlay.length < lastPlay.length) return false;
   765→            }
   766→            return newPlay.value > lastPlay.value;
   767→        }
   768→        return false;
