   771→    playCards(playerId, cards) {
   772→        if (!this.gameState.started) return { success: false, message: '游戏未开始' };
   773→
   774→        const playerIds = this.getSortedPlayerIds();
   775→        if (playerIds[this.gameState.currentPlayer] !== playerId) return { success: false, message: '不是你的回合' };
   776→
   777→        // 清除回合计时器
   778→        this.clearTurnTimer();
   779→
   780→        const player = this.players.get(playerId);
   781→        if (player.finished) return { success: false, message: '你已经出完牌了' };
   782→
   783→        // 从服务端手牌中获取实际的牌（确保value正确）
   784→        const hand = this.gameState.hands[playerId];
   785→        const actualCards = [];
   786→        for (const card of cards) {
   787→            const idx = hand.findIndex(c => c.suit === card.suit && c.rank === card.rank);
   788→            if (idx === -1) return { success: false, message: '你没有这张牌' };
   789→            actualCards.push(hand[idx]);
   790→        }
   791→
   792→        const result = this.validatePlay(actualCards);
   793→        if (!result.valid) return { success: false, message: '无效的牌型' };
   794→
   795→        if (this.gameState.lastPlay && this.gameState.lastPlayer !== playerId) {
   796→            if (!this.comparePlay(result, this.gameState.lastPlay)) return { success: false, message: '牌不够大' };
   797→        }
   798→
   799→        // 从手牌中移除
   800→        for (const card of actualCards) {
   801→            const idx = hand.findIndex(c => c.suit === card.suit && c.rank === card.rank);
   802→            hand.splice(idx, 1);
   803→        }
