   829→    pass(playerId, broadcastPass = true) {
   830→        if (!this.gameState.started) return { success: false, message: '游戏未开始' };
   831→        const playerIds = this.getSortedPlayerIds();
   832→        if (playerIds[this.gameState.currentPlayer] !== playerId) return { success: false, message: '不是你的回合' };
   833→
