   837→        const player = this.players.get(playerId);
   838→        if (player.finished) return { success: false, message: '你已经出完牌了' };
   839→        if (!this.gameState.lastPlay || this.gameState.lastPlayer === playerId) return { success: false, message: '你必须出牌' };
